async function answerListSessions(
  ws: WebSocket,
  store: SessionStore | undefined,
  request: ListSessionsMessage
): Promise<void> {
  if (!store?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'The session store cannot list conversations');
    return;
  }
  const {userId} = ws as ExtWebSocket;
  let summaries: SessionSummary[];
  try {
    summaries = await store.listFor(userId, {limit: request.limit, before: request.before});
